// (The docs once cited this file as existing; it did not.)
import test from "node:test";
import assert from "node:assert/strict";
import {
  PING_EVERY_MS, STALE_AFTER_MS, DEAD_AFTER_MS, AWAY_HOLD_MS,
  standingOf, shouldRelink, isLive,
  revokeEntry, isRevoked, withRevoked, withoutRevoked,
} from "./liveness.js";

const NOW = 1_000_000_000;
const rec = (over = {}) => ({ status: "ready", peer: { opened: true }, hello: { modelId: "m" }, lastSeen: NOW, ...over });
const at = (r, silentMs) => standingOf({ ...r, lastSeen: NOW - silentMs }, NOW);

test("the stated bounds are 3 and 6 missed pings", () => {
  assert.equal(STALE_AFTER_MS, 3 * PING_EVERY_MS);
  assert.equal(DEAD_AFTER_MS, 6 * PING_EVERY_MS);
});

test("silence walks ready → stale → dead at exactly the bounds", () => {
  const r = rec();
  assert.equal(at(r, 0), "ready");
  assert.equal(at(r, STALE_AFTER_MS - 1), "ready");
  assert.equal(at(r, STALE_AFTER_MS), "stale");
  assert.equal(at(r, DEAD_AFTER_MS - 1), "stale");
  assert.equal(at(r, DEAD_AFTER_MS), "dead");
});

test("a ping resets a stale horse to ready", () => {
  const r = rec({ lastSeen: NOW - STALE_AFTER_MS - 5 });
  assert.equal(standingOf(r, NOW), "stale");
  r.lastSeen = NOW;
  assert.equal(standingOf(r, NOW), "ready");
});

test("never convict on absence alone: unheard-from is linking, not dead", () => {
  assert.equal(standingOf(rec({ lastSeen: null, hello: null }), NOW), "linking");
  assert.equal(standingOf(rec({ lastSeen: null }), NOW), "ready"); // hello seen, no ping yet
  assert.equal(standingOf(rec({ peer: { opened: false } }), NOW), "linking");
});

test("a relay record that never said hello and went silent still dies at the bound", () => {
  assert.equal(at(rec({ hello: null }), 100_000), "dead");
});

test("a hidden (backgrounded) horse is held away, then given up on after AWAY_HOLD_MS", () => {
  const r = rec({ hidden: true });
  assert.equal(at(r, DEAD_AFTER_MS + 1), "away");
  assert.equal(at(r, AWAY_HOLD_MS - 1), "away");
  assert.equal(at(r, AWAY_HOLD_MS), "dead");
});

test("lost and expired are reported as such", () => {
