// falls back to the upstream when none is attached, and a pinned model is never redirected.
import test from "node:test";
import assert from "node:assert/strict";
import http from "node:http";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createBridge } from "./bridge-server.mjs";

const WEBLLM = "gemma-2-2b-it-q4f16_1-MLC";

function fakeUpstream() {
  const server = http.createServer((req, res) => {
    let raw = ""; req.on("data", (c) => (raw += c));
    req.on("end", () => { res.writeHead(200, { "content-type": "application/json" }); res.end(JSON.stringify({ id: "up", object: "chat.completion", model: "upstream", choices: [{ index: 0, message: { role: "assistant", content: "upstream-answer" }, finish_reason: "stop" }] })); });
  });
  return new Promise((r) => server.listen(0, "127.0.0.1", () => r({ server, base: `http://127.0.0.1:${server.address().port}` })));
}

/** A controller tab: connects to the SSE channel, publishes one ready WebLLM worker, answers every job it is sent. */
async function attachTab(base, { model = WEBLLM, text = "webllm-answer", seen = [] } = {}) {
  const ctl = new AbortController();
  const r = await fetch(base + "/bridge/events", { signal: ctl.signal });
  (async () => {
    const dec = new TextDecoder(); let buf = "";
    try {
      for await (const chunk of r.body) {
        buf += dec.decode(chunk, { stream: true });
        let i;
        while ((i = buf.indexOf("\n\n")) >= 0) {
          const ev = buf.slice(0, i); buf = buf.slice(i + 2);
          const line = ev.split("\n").find((l) => l.startsWith("data:"));
          if (!line) continue;
          const m = JSON.parse(line.slice(5));
          if (m.type !== "job") continue;
          seen.push(m);
          await fetch(base + "/bridge/reply", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify([{ id: m.id, type: "token", text }, { id: m.id, type: "result", text }]) });
        }
      }
    } catch { /* closed */ }
  })();
  await fetch(base + "/bridge/state", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ workers: [{ ready: true, model, queueDepth: 0 }] }) });
  return { seen, close: () => ctl.abort() };
}

const ask = (base, body) => fetch(base + "/v1/chat/completions", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ stream: false, messages: [{ role: "user", content: "hi" }], ...body }) });

async function withBridge(fn) {
  const up = await fakeUpstream();
  const bridge = createBridge({ port: 0, host: "127.0.0.1", dist: tmpdir(), upstream: up.base, linksFile: join(tmpdir(), "webllm-default-" + Date.now() + Math.random() + ".json"), autoOpen: false });
  const addr = await bridge.listen();
  try { await fn(`http://127.0.0.1:${addr.port}`); } finally { await bridge.close(); up.server.close(); }
}

test("no model named + a ready WebLLM worker → the worker answers, and the job carries no pinned model", async () => {
  await withBridge(async (base) => {
    const tab = await attachTab(base);
    try {
      const r = await ask(base, {});
      assert.equal(r.status, 200);
      const j = await r.json();
      assert.equal(j.choices[0].message.content, "webllm-answer");
      assert.equal(tab.seen.length, 1);
      assert.equal(tab.seen[0].model, null, "the worker uses whatever it has loaded");
    } finally { tab.close(); }
  });
});

test("no model named + no worker attached → unchanged: it goes to the upstream", async () => {
  await withBridge(async (base) => {
    const r = await ask(base, {});
    assert.match(await r.text(), /upstream-answer/);
  });
});

