// The one place defaults live. Nothing else in the repo hard-codes a port.
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

export const DEFAULT_PORT = 8800;
export const DEFAULT_HOST = "127.0.0.1";
export const DEFAULT_COMPAT_PORT = 11434; // Ollama's well-known port, used only when the compat listener is switched on
export const DEFAULT_OLLAMA = "http://127.0.0.1:11435"; // real Ollama stays private

export const ROOT = fileURLToPath(new URL("..", import.meta.url));

export function readVersion() {
  try {
    return JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8")).version || "0.0.0";
  } catch {
    return "0.0.0";
  }
}

function port(v, dflt) {
  if (v === undefined || v === null || v === "") return dflt;
  const n = Number(v);
  return Number.isInteger(n) && n >= 0 && n < 65536 ? n : dflt;
}

/** FOLD_COMPAT_PORT: unset/""/0/off/false -> off (null); on/true/1 -> DEFAULT_COMPAT_PORT; a number -> that port. */
export function compatPortFrom(v) {
  if (v === undefined || v === null) return null;
  const s = String(v).trim().toLowerCase();
  if (s === "" || s === "0" || s === "off" || s === "false" || s === "no") return null;
  if (s === "on" || s === "true" || s === "1" || s === "yes") return DEFAULT_COMPAT_PORT;
  const n = Number(s);
  return Number.isInteger(n) && n > 1 && n < 65536 ? n : null;
}

export function loadConfig(env = process.env) {
  const home = env.FOLD_HOME || join(homedir(), ".fold");
  return {
    port: port(env.FOLD_PORT, DEFAULT_PORT),
    host: env.FOLD_HOST || DEFAULT_HOST,
    compatPort: compatPortFrom(env.FOLD_COMPAT_PORT),
    home,
    organsSpec: env.FOLD_ORGANS || "",
    organsDir: env.FOLD_ORGANS_DIR || "",
    ollama: (env.FOLD_OLLAMA || DEFAULT_OLLAMA).replace(/\/+$/, ""),
    uiDir: env.FOLD_UI_DIR || join(ROOT, "ui"),
    url: (env.FOLD_URL || "").replace(/\/+$/, ""),
  };
}

export function baseUrl(cfg) {
  return cfg.url || `http://127.0.0.1:${cfg.port}`;
}
