import http from "node:http";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

export function tmp(prefix = "fold-test-") {
  const d = mkdtempSync(join(tmpdir(), prefix));
  return { dir: d, cleanup: () => rmSync(d, { recursive: true, force: true }) };
}

/** A fake organ. `routes` maps "METHOD /path" -> (req,res) handler; anything else declines (returns false). */
export function fakeOrgan(name, routes = {}, extra = {}) {
  return {
    name,
    mode: "inproc",
    async handle(req, res) {
      const key = `${req.method} ${(req.url || "").split("?")[0]}`;
      const h = routes[key];
      if (!h) return false;
      await h(req, res);
      return true;
    },
    close() { this.closed = true; },
    ...extra,
  };
}

export const json = (res, status, body) => {
  const t = JSON.stringify(body);
  res.writeHead(status, { "content-type": "application/json", "content-length": Buffer.byteLength(t) });
  res.end(t);
};

/** Minimal request helper (not fetch: keeps connection control explicit). */
export function request(port, { method = "GET", path = "/", headers = {}, body = null } = {}) {
  return new Promise((resolve, reject) => {
    const req = http.request({ host: "127.0.0.1", port, method, path, headers, agent: false }, (res) => {
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => {
        const text = Buffer.concat(chunks).toString("utf8");
        let j = null;
        try { j = JSON.parse(text); } catch { /* not json */ }
        resolve({ status: res.statusCode, headers: res.headers, text, json: j });
      });
      res.on("error", reject);
    });
    req.on("error", reject);
    if (body != null) req.write(body);
    req.end();
  });
}

export function listenEphemeral(handler) {
  return new Promise((resolve) => {
    const server = http.createServer(handler);
    server.listen(0, "127.0.0.1", () => resolve({
      server,
      port: server.address().port,
      close: () => new Promise((r) => { server.closeAllConnections?.(); server.close(() => r()); }),
    }));
  });
}

export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export async function waitFor(fn, ms = 3000, step = 20) {
  const t0 = Date.now();
  while (Date.now() - t0 < ms) {
    if (await fn()) return true;
    await sleep(step);
  }
  return false;
}
