export async function cmdServe({ env, err }) {
  const first = loadConfig(env);
  const dirs = ensureHome(first.home);
  const applied = loadEnvFile(dirs.envFile, env); // names only; values never printed
  const cfg = loadConfig(env);
  const logFile = join(dirs.logs, "fold.log");
  const log = (msg) => {
    const line = `${new Date().toISOString()} ${msg}`;
    err(line);
    try { appendFileSync(logFile, line + "\n", { mode: 0o600 }); } catch { /* logging must never kill the server */ }
  };
  if (applied.length) log(`fold.env supplied: ${applied.join(", ")}`);
  const organs = buildOrgans({ cfg, env, log });
  const fold = createFold({ port: cfg.port, host: cfg.host, compatPort: cfg.compatPort, organs, home: cfg.home, log, uiDir: cfg.uiDir });
  const { port, compatPort } = await fold.listen();
  log(`fold ${readVersion()} up on http://${cfg.host}:${port}${compatPort != null ? `, compat on :${compatPort}` : ""}; organs: ${organs.map((o) => `${o.name}=${o.mode}`).join(" ")}`);
  const stop = async (sig) => { log(`${sig}: shutting down`); await fold.close(); process.exit(0); };
  process.once("SIGINT", () => stop("SIGINT"));
  process.once("SIGTERM", () => stop("SIGTERM"));
  return fold;
}

