import { copyFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";

/** Set process.env[k] = v for every key that is not already set (an operator's explicit value always wins). Returns the keys applied. */
export function setDefaults(map, env = process.env) {
  const applied = [];
  for (const [k, v] of Object.entries(map)) {
