  }
  return applied;
}

/** Copy `from` to `to` once, never over an existing file (seeding a relocated default). Returns true when copied. */
export function seedFile(from, to) {
  try {
    if (existsSync(to) || !existsSync(from)) return false;
    mkdirSync(dirname(to), { recursive: true });
    copyFileSync(from, to);
    return true;
  } catch { return false; }
}

export const joinData = (dataDir, ...p) => join(dataDir, ...p);

export const truthy = (v) => /^(1|true|yes|on)$/i.test(String(v ?? "").trim());
